// ===== v13: 运行时探测 App 是否具备 HLS 播放能力 =====
// LegadoTeam 版 build.gradle 注释掉了 media3-exoplayer-hls，
// 运行时 HlsMediaSource 为 JavaPackage(非 function) ⇒ 任何 m3u8 都播不了。
// 探测一次后缓存到书源变量 acHls。
function AC_HLS(sv){
 var c='';try{c=AC_g(sv,'acHls');}catch(e){c='';}
 if(c==='1')return true;
 if(c==='0')return false;
 var ok=false;
 try{
  var o=Packages;var ps='androidx.media3.exoplayer.hls.HlsMediaSource'.split('.');
  var bad=false;
  for(var i=0;i<ps.length;i++){
   try{o=o[ps[i]];}catch(e){bad=true;break;}
   if(o===undefined||o===null){bad=true;break;}
  }
  ok=(!bad)&&(typeof o==='function');
 }catch(e){ok=false;}
 try{AC_s(sv,'acHls',ok?'1':'0');}catch(e2){}
 return ok;
}
