 if(d&&d.domain){dom=AC_nor(d.domain);}
 var list=(d&&d.imgList)?d.imgList:[];
 if(!list.length)return '';
 var out='';
 for(var i=0;i<list.length;i++){
   var dd=pool.length?pool[i%pool.length]:dom;
   var u=AC_img(dd,String(list[i]));
   if(u)out=out+'<img src="'+u+'"/><br/>';
 }
 return out;}

//图片版本参数：写进书源变量，清缓存后 bump 一次即可全部重下
function AC_vq(sv){
 var v=AC_g(sv,'acImgVer');
 if(!v){v='1';AC_s(sv,'acImgVer',v);}
 return '?v='+v;
}
function AC_vimg(dom,p,vq){
 var u=AC_img(dom,p);
 if(!u)return u;
 if(u.indexOf('?')>=0)return u+'&v='+String(vq).substring(2);
 return u+vq;
