//★★★封面 data: 内置（唯一可行路径）
//coverDecodeJs 走不通：BookCover.load 不传 sourceOrigin → OkHttpStreamFetcher.source=null
//→ ImageUtils.decode 里 source?.evalJS 恒为 null，钩子永不执行
//这里在规则侧就完成 下载→XOR解密→base64，data: URL 自带已解密字节
function AC_bake(sv,jv,u){
try{
if(!u||u.indexOf('http')!==0)return u;
if(u.indexOf('data:')===0)return u;
var r=jv.get(u,null,30000);
if(!r)return u;
var b=r.bodyAsBytes();
if(!b||b.length<100)return u;
//★体积护栏：部分封面达 3MB+，base64 后 4MB 会让详情页卡死；超限退回网络 URL
if(b.length>1200000)return u;
var K='2020-zq3-888';
for(var i=0;i<100;i++){var v=(b[i]&255)^K.charCodeAt(i%12);b[i]=(v>127)?(v-256):v;}
var h0=b[0]&255,h1=b[1]&255;
var mime='image/jpeg';
if(h0===0x89&&h1===0x50)mime='image/png';
else if(h0===0x52&&h1===0x49)mime='image/webp';
else if(h0!==0xff||h1!==0xd8)return u;
return 'data:'+mime+';base64,'+String(Packages.android.util.Base64.encodeToString(b,2));
}catch(e){return u;}
}

//★★★把 m3u8 清单转成 MPD（供正文返回，走 .mpd 文件分支）
function AC_MPD(sv,jv,d){
try{
var p=String(d.videoUrl||'');var ak=String(d.authKey||'');
if(!p||!ak)return '';
 var u=AC_DFT+'/api/m3u8/public/decode/authPath?path='+AC_ue(p)+'&auth_key='+AC_ue(ak)+'&hevc=1';
var m=String(jv.ajax(u+AC_OPT(sv)));
if(m.indexOf('#EXTM3U')!==0)return '';
var L=m.split('\n');
var segs=[],durs=[],i,t,km,dm;
for(i=0;i<L.length;i++){
 t=String(L[i]).trim();
 if(t.indexOf('#EXTINF')===0){dm=t.match(/([0-9.]+)/);if(dm)durs.push(parseFloat(dm[1]));}
 else if(t.indexOf('http')===0)segs.push(t);
}
if(!segs.length)return '';
var total=0;for(i=0;i<durs.length;i++)total+=durs[i];
if(!total)total=segs.length*4;
var T=Math.round(total);
var x='<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n';
x+='<MPD xmlns=\"urn:mpeg:dash:schema:mpd:2011\" type=\"static\" mediaPresentationDuration=\"PT'+T+'S\" minBufferTime=\"PT2S\">\n';
x+='<Period duration=\"PT'+T+'S\">\n';
x+='<AdaptationSet mimeType=\"video/mp2t\" segmentAlignment=\"true\" startWithSAP=\"0\">\n';
x+='<Representation id=\"1\" bandwidth=\"800000\">\n';
x+='<SegmentList timescale=\"1000\" duration=\"4000\">\n';
for(i=0;i<segs.length;i++)x+='<SegmentURL media=\''+AC_esc(segs[i])+'\'/>\n';
x+='</SegmentList>\n</Representation>\n</AdaptationSet>\n</Period>\n</MPD>';
return x;
}catch(e){return '';}
}

