  for(var fi=0;fi<fc.length;fi++){var fch=fc[fi];
    out.push(JSON.stringify({n:pre+String(fch.chapterTitle||('第'+(fi+1)+'集')),
      u:AC_HOST(sv)+'/api/fiction/base/chapterInfo?chapterId='+String(fch.chapterId)+'&fictionId='+id.id}));}
}else if(id.type==='comic'){
  var d=AC_get(sv,jv,'/api/comics/base/public/info',AC_q({comicsId:id.id})).data;
  var cl=d.chapterList||[];
  for(var i=0;i<cl.length;i++){var c=cl[i];
    out.push(JSON.stringify({n:String(c.chapterTitle||('第'+(i+1)+'话')),
      u:AC_HOST(sv)+'/api/comics/base/public/chapterInfo?chapterId='+String(c.chapterId)+'&comicsId='+id.id}));}
}else{
  var v=AC_get(sv,jv,'/api/video/public/getVideoById',AC_q({videoId:id.id})).data;
  if(v.videoId===undefined||v.videoId===null||v.videoId==='')v.videoId=id.id;
  if(v.videoSerial&&v.videoSerialPc&&v.videoSerialPc.length>1){
    for(var k=0;k<v.videoSerialPc.length;k++){var e=v.videoSerialPc[k];
      var vid=String(e.videoId);
      out.push(JSON.stringify({n:String(e.title||('第'+(k+1)+'集')),
        u:AC_HOST(sv)+'/v/'+vid}));
      out.push(JSON.stringify({n:'    ▶ 内置浏览器播放本集',u:AC_HOST(sv)+'/v/'+vid+'?lgwb=1'}));}
  }else{
    var mn=Math.round(Number(v.playTime||0)/60);
    out.push(JSON.stringify({n:String(v.title||'正片')+' ('+mn+'分钟)',u:id.host+'/v/'+id.id}));
    out.push(JSON.stringify({n:'▶ 内置浏览器播放（推荐）',u:id.host+'/v/'+id.id+'?lgwb=1'}));
  }
}
return out;})()
